import{_ as a,o as i,c as l,a as r}from"./chunks/framework.Ld7uezS_.js";const _=JSON.parse('{"title":"报警与水系统零基础前置补强概览","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/overview-2026-08-21-alarm-water-prerequisite.md","filePath":"outputs/overview-2026-08-21-alarm-water-prerequisite.md","lastUpdated":1787283889000}'),t={name:"outputs/overview-2026-08-21-alarm-water-prerequisite.md"};function o(d,e,s,u,c,h){return i(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="报警与水系统零基础前置补强概览" tabindex="-1">报警与水系统零基础前置补强概览 <a class="header-anchor" href="#报警与水系统零基础前置补强概览" aria-label="Permalink to &quot;报警与水系统零基础前置补强概览&quot;">​</a></h1><h2 id="本轮目标" tabindex="-1">本轮目标 <a class="header-anchor" href="#本轮目标" aria-label="Permalink to &quot;本轮目标&quot;">​</a></h2><p>继续按“逐段阅读、零基础复述”的标准审查报警系统、水系统和理论消防设施章节，修复把专业前置知识默认成已知的问题。</p><h2 id="主要补强" tabindex="-1">主要补强 <a class="header-anchor" href="#主要补强" aria-label="Permalink to &quot;主要补强&quot;">​</a></h2><h3 id="_1-火灾自动报警系统" tabindex="-1">1. 火灾自动报警系统 <a class="header-anchor" href="#_1-火灾自动报警系统" aria-label="Permalink to &quot;1. 火灾自动报警系统&quot;">​</a></h3><ul><li>解释建筑位置与系统定位的区别；</li><li>解释区域、回路、设备地址、模块分别解决什么问题；</li><li>增加“建筑地图 + 系统地图”的对应关系；</li><li>用“回路 3、地址 018、某房间感烟探测器”示例说明从控制器定位到现场核对的过程；</li><li>明确控制器显示、现场动作、反馈信号不能互相替代。</li></ul><h3 id="_2-消防给水和自动灭火系统" tabindex="-1">2. 消防给水和自动灭火系统 <a class="header-anchor" href="#_2-消防给水和自动灭火系统" aria-label="Permalink to &quot;2. 消防给水和自动灭火系统&quot;">​</a></h3><ul><li>按水流方向学习设备识别：水源、储水、加压、分区控制、管网、出水、反馈；</li><li>区分控制阀、水流指示器、压力开关；</li><li>区分水力证据、机械/设备证据和控制/反馈证据；</li><li>明确局部压力、泵运行或末端有水都不能单独推出全系统结论。</li></ul><h3 id="_3-理论与课程同步" tabindex="-1">3. 理论与课程同步 <a class="header-anchor" href="#_3-理论与课程同步" aria-label="Permalink to &quot;3. 理论与课程同步&quot;">​</a></h3><ul><li>理论消防设施章节补充“探测器是把火灾特征转换为控制器输入的设备”的前置解释；</li><li>综合学习课补充两套地图和三类证据的学习方法；</li><li>术语表新增回路、设备地址、控制阀、水力证据、反馈证据；</li><li>训练导航增加回路/地址定位与水力/反馈证据提示；</li><li>更新项目总览和当日工作记忆。</li></ul><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><ul><li><code>git diff --check</code>：通过；</li><li>理论题卡：T01-T39，共 39 张，无缺号、无重复；</li><li>技能题卡：S01-S49，共 49 张，无缺号、无重复；</li><li>排除 <code>outputs/</code>、<code>node_modules/</code> 和 <code>.workbuddy/</code> 后，站内绝对链接缺失：0；</li><li>未运行项目既有的 VitePress <code>imports</code> 构建问题；</li><li>本轮未引入新依赖，未改变考试固定口径或危险操作边界。</li></ul>',12)])])}const m=a(t,[["render",o]]);export{_ as __pageData,m as default};
